package io.tenvyr.control.runtime;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.Json;
import java.util.*;

public final class Coordination {
    public static final Set<String> TERMINAL=Set.of("ACCEPTED","FAILED","CANCELLED","LIMIT_REACHED");
    private Coordination(){}
    public static String modelId(JsonNode value){String id=string(value,"modelId",256);if(!id.matches("[A-Za-z0-9][A-Za-z0-9._/\\-:@+]*"))throw fail("CONFIG_INVALID","Invalid modelId");return id;}
    public static ObjectNode selection(JsonNode raw){if(raw==null||!raw.isObject()||!Set.of("agent","connection").contains(Json.text(raw,"kind")))throw fail("CONFIG_INVALID","Selection must name an agent or connection");String name=string(raw.get("name"),"selection name",255);ObjectNode out=Json.object("kind",raw.get("kind"),"name",name);if(Json.text(raw,"kind").equals("connection"))RuntimeConnectionService.validateId(name);if(raw.has("agent"))out.put("agent",string(raw.get("agent"),"agent",255));return out;}
    public static ObjectNode target(JsonNode raw){if(raw==null||!raw.isObject())throw fail("CONFIG_INVALID","Runtime target must be an object");String id=string(raw.get("connectionId"),"connectionId",255);RuntimeConnectionService.validateId(id);ObjectNode out=Json.object("connectionId",id);if(raw.has("modelId"))out.put("modelId",modelId(raw.get("modelId")));return out;}
    public static ObjectNode parseConfig(JsonNode raw){schema(raw,"CONFIG_INVALID");ObjectNode out=Json.object("schemaVersion",1,"planner",selection(raw.get("planner")),"verifier",selection(raw.get("verifier")));ArrayNode workers=Json.array();array(raw.get("allowedWorkers"),"allowedWorkers",1,128).forEach(n->workers.add(selection(n)));out.set("allowedWorkers",workers);for(var bound:Map.of("maxIterations",100L,"maxWorkersPerIteration",64L,"maxTotalWorkers",1024L,"loopDeadlineMs",31536000000L).entrySet())out.put(bound.getKey(),integer(raw.get(bound.getKey()),bound.getKey(),1,bound.getValue()));out.put("delegationDepthMax",raw.has("delegationDepthMax")?integer(raw.get("delegationDepthMax"),"delegationDepthMax",0,3):3);ArrayNode executors=Json.array();array(raw.get("allowedExecutors"),"allowedExecutors",1,32).forEach(n->executors.add(string(n,"executor",255)));out.set("allowedExecutors",executors);for(String role:List.of("planner","verifier"))if(raw.has(role+"Target")){ObjectNode target=target(raw.get(role+"Target"));if(!Json.text(out.path(role),"kind").equals("connection")||!Json.text(out.path(role),"name").equals(Json.text(target,"connectionId")))throw fail("CONFIG_INVALID","Role target must match its selected connection");out.set(role+"Target",target);}if(raw.has("allowedTargets")){ArrayNode targets=Json.array();for(JsonNode entry:array(raw.get("allowedTargets"),"allowedTargets",1,128)){ObjectNode target=target(entry);if(findSelection(workers,"connection",Json.text(target,"connectionId"))==null)throw fail("CONFIG_INVALID","Target is not an allowed connection worker");targets.add(target);}out.set("allowedTargets",targets);}if(raw.has("budgetAccountId"))out.put("budgetAccountId",string(raw.get("budgetAccountId"),"budgetAccountId",255));return out;}
    public static ObjectNode parseBatch(JsonNode raw){schema(raw,"BATCH_INVALID");ObjectNode result=Json.object("schemaVersion",1,"iterationNumber",integer(raw.get("iterationNumber"),"iterationNumber",1,100),"baseRevision",integer(raw.get("baseRevision"),"baseRevision",1,Integer.MAX_VALUE),"reason",string(raw.get("reason"),"reason",2048));ArrayNode tasks=Json.array();Set<String> ids=new HashSet<>();for(JsonNode task:array(raw.get("tasks"),"tasks",1,64)){String id=string(task.get("taskId"),"taskId",100);if(!id.matches("[A-Za-z0-9_.:\\-]+")||!ids.add(id))throw fail("BATCH_INVALID","Task IDs must be distinct safe identifiers");if(!task.path("required").isBoolean())throw fail("TASK_INVALID","Task required must be boolean");JsonNode input=task.has("input")?task.get("input"):NullNode.instance;bytes(input,65536,"TASK_INVALID");ArrayNode deps=Json.array();Set<String> seen=new HashSet<>();JsonNode rawDeps=task.has("dependsOn")?task.get("dependsOn"):Json.array();for(JsonNode dep:array(rawDeps,"dependsOn",0,16)){String value=string(dep,"dependency",100);if(!value.matches("[A-Za-z0-9_.:\\-]+")||value.equals(id)||!seen.add(value))throw fail("TASK_INVALID","Invalid dependency");deps.add(value);}ObjectNode parsed=Json.object("taskId",id,"agent",string(task.get("agent"),"agent",255),"input",input,"dependsOn",deps,"required",task.get("required"),"reason",string(task.get("reason"),"reason",2048));if(task.has("connectionId")){String connection=string(task.get("connectionId"),"connectionId",255);RuntimeConnectionService.validateId(connection);parsed.put("connectionId",connection);}if(task.has("modelId")){if(!parsed.has("connectionId"))throw fail("TASK_INVALID","Model requires a connection");parsed.put("modelId",modelId(task.get("modelId")));}if(task.has("timeoutMs"))parsed.put("timeoutMs",integer(task.get("timeoutMs"),"timeoutMs",1,86400000));if(task.has("retry"))parsed.put("retry",integer(task.get("retry"),"retry",0,10));tasks.add(parsed);}Map<String,JsonNode> byId=new HashMap<>();tasks.forEach(t->byId.put(Json.text(t,"taskId"),t));for(JsonNode task:tasks)for(JsonNode dep:task.path("dependsOn"))if(!byId.containsKey(dep.asText()))throw fail("BATCH_INVALID","Unknown dependency");Set<String> visiting=new HashSet<>(),visited=new HashSet<>();for(String id:ids)visit(id,byId,visiting,visited);result.set("tasks",tasks);bytes(raw,262144,"BATCH_INVALID");return result;}
    private static void visit(String id,Map<String,JsonNode> tasks,Set<String> visiting,Set<String> visited){if(visited.contains(id))return;if(!visiting.add(id))throw fail("BATCH_INVALID","Task dependency cycle");for(JsonNode dep:tasks.get(id).path("dependsOn"))visit(dep.asText(),tasks,visiting,visited);visiting.remove(id);visited.add(id);}
    public static void validateBatch(JsonNode config,JsonNode proposal,int cumulative){if(Json.integer(proposal,"iterationNumber",0)>Json.integer(config,"maxIterations",0)||proposal.path("tasks").size()>Json.integer(config,"maxWorkersPerIteration",0)||cumulative+proposal.path("tasks").size()>Json.integer(config,"maxTotalWorkers",0))throw fail("LIMIT_EXCEEDED","Task batch exceeds frozen bounds");for(JsonNode task:proposal.path("tasks")){boolean connection=task.has("connectionId");String name=connection?Json.text(task,"connectionId"):Json.text(task,"agent");JsonNode allowed=findSelection(config.path("allowedWorkers"),connection?"connection":"agent",name);if(allowed==null)throw fail(connection?"CONNECTION_NOT_ALLOWED":"AGENT_NOT_ALLOWED","Worker is not allowed");String agent=connection?Json.text(allowed,"agent",toTransportAgent(name)):name;if(!agent.equals(Json.text(task,"agent")))throw fail("AGENT_NOT_ALLOWED","Connection routing agent mismatch");for(String role:List.of("planner","verifier"))if(Json.text(config.path(role),"kind").equals(connection?"connection":"agent")&&Json.text(config.path(role),"name").equals(name))throw fail("AGENT_NOT_ALLOWED","Coordinator role cannot be selected as a worker");List<JsonNode> targets=new ArrayList<>();for(JsonNode target:config.path("allowedTargets"))if(Json.text(target,"connectionId").equals(name))targets.add(target);if(task.has("modelId")&&targets.stream().noneMatch(t->Objects.equals(t.get("modelId"),task.get("modelId"))))throw fail("MODEL_NOT_ALLOWED","Model outside frozen targets");if(!task.has("modelId")&&targets.size()>1)throw fail("MODEL_NOT_ALLOWED","Worker must specify its allowed model");}}
    private static JsonNode findSelection(JsonNode list,String kind,String name){for(JsonNode n:list)if(Json.text(n,"kind").equals(kind)&&Json.text(n,"name").equals(name))return n;return null;}
    public static ObjectNode parseDecision(JsonNode raw){schema(raw,"DECISION_INVALID");String action=string(raw.get("action"),"action",32);if(!Set.of("ACCEPT","CONTINUE","FAIL","WAIT_FOR_HUMAN").contains(action))throw fail("DECISION_INVALID","Unknown verifier action");ArrayNode refs=Json.array();array(raw.get("evidenceRefs"),"evidenceRefs",0,64).forEach(n->refs.add(string(n,"evidenceRef",255)));ObjectNode out=Json.object("schemaVersion",1,"iterationId",string(raw.get("iterationId"),"iterationId",255),"iterationNumber",integer(raw.get("iterationNumber"),"iterationNumber",1,100),"action",action,"reason",string(raw.get("reason"),"reason",2048),"evidenceRefs",refs);if(raw.has("recommendation")){JsonNode r=raw.get("recommendation");ArrayNode focus=Json.array();array(r.get("focus"),"focus",0,16).forEach(n->focus.add(string(n,"focus",255)));ObjectNode rec=Json.object("reason",string(r.get("reason"),"reason",2048),"focus",focus);bytes(rec,16384,"DECISION_INVALID");out.set("recommendation",rec);}return out;}
    public static String transition(String phase,String event){if(TERMINAL.contains(phase))return phase;String next=switch(event){case "plannerProposed"->"BATCH_VALIDATION";case "batchRejected","continue"->"PLANNING";case "batchValidated"->"WORKING";case "workersFinished"->"VERIFYING";case "verifierProposed","approvalGranted"->"DECIDING";case "accept"->"ACCEPTED";case "fail","approvalDenied"->"FAILED";case "wait"->"WAITING_FOR_HUMAN";case "deadline","limitReached"->"LIMIT_REACHED";case "cancel"->"CANCELLED";default->throw fail("PHASE_TRANSITION_INVALID","Unknown event");};Set<String> from=switch(event){case "plannerProposed","batchRejected"->Set.of("PLANNING");case "batchValidated"->Set.of("BATCH_VALIDATION");case "workersFinished"->Set.of("WORKING");case "verifierProposed"->Set.of("VERIFYING");case "accept","continue","wait"->Set.of("DECIDING");case "approvalGranted","approvalDenied"->Set.of("WAITING_FOR_HUMAN");default->Set.of("PLANNING","BATCH_VALIDATION","WORKING","VERIFYING","DECIDING","WAITING_FOR_HUMAN");};if(!from.contains(phase))throw fail("PHASE_TRANSITION_INVALID","Illegal coordination phase event");return next;}
    public static boolean continueAllowed(JsonNode config,int iteration,int cumulative,int next){return iteration<Json.integer(config,"maxIterations",0)&&cumulative+next<=Json.integer(config,"maxTotalWorkers",0);}
    public static String toTransportAgent(String id){return id.startsWith("conn:")?"conn__"+id.substring(5).replaceAll("[^A-Za-z0-9_.-]","_"):id.replaceAll("[^A-Za-z0-9_.-]","_");}
    public static ObjectNode compilePatch(JsonNode config,JsonNode batch,JsonNode workspace,String goal,JsonNode identity){ArrayNode operations=Json.array();for(JsonNode task:batch.path("tasks")){ObjectNode input=Json.object("schemaVersion",1,"role","worker","taskId",task.get("taskId"),"goal",goal,"iterationNumber",batch.get("iterationNumber"),"taskInput",task.get("input"),"workspace",workspace,"executionWorkspace",identity,"outputContract",Json.object("instructions","Execute the assigned task in the execution workspace and return structured output."));boolean required=Json.bool(task,"required",false);ObjectNode step=Json.object("id",task.get("taskId"),"agent",task.get("agent"),"input",input,"dependsOn",task.get("dependsOn"),"onFailure",required?(Json.integer(task,"retry",0)>0?"retry":"stop"):"continue");if(task.has("timeoutMs"))step.set("timeout",task.get("timeoutMs"));if(Json.integer(task,"retry",0)>0)step.set("retries",task.get("retry"));if(task.has("connectionId")){ObjectNode metadata=Json.object("tenvyrConnectionId",task.get("connectionId"));JsonNode model=task.get("modelId");if(model==null){List<JsonNode> targets=new ArrayList<>();for(JsonNode target:config.path("allowedTargets"))if(target.get("connectionId").equals(task.get("connectionId")))targets.add(target);if(targets.size()==1)model=targets.get(0).get("modelId");}if(model!=null)metadata.set("tenvyrModelId",model);step.set("metadata",metadata);}operations.add(Json.object("op","addStep","step",step));}JsonNode verifier=config.path("verifier");ArrayNode deps=Json.array();batch.path("tasks").forEach(t->deps.add(t.get("taskId")));ObjectNode step=Json.object("id","verify-"+Json.integer(batch,"iterationNumber",0),"agent",Json.text(verifier,"kind").equals("connection")?toTransportAgent(Json.text(verifier,"agent",Json.text(verifier,"name"))):Json.text(verifier,"agent",Json.text(verifier,"name")),"input",Json.object(),"dependsOn",deps,"onFailure","stop");if(Json.text(verifier,"kind").equals("connection")){ObjectNode meta=Json.object("tenvyrConnectionId",verifier.get("name"));if(config.path("verifierTarget").has("modelId"))meta.set("tenvyrModelId",config.path("verifierTarget").get("modelId"));step.set("metadata",meta);}operations.add(Json.object("op","addStep","step",step));return Json.object("schemaVersion",1,"baseRevision",batch.get("baseRevision"),"operations",operations);}
    static void schema(JsonNode n,String code){if(n==null||!n.isObject()||!n.path("schemaVersion").isIntegralNumber()||n.path("schemaVersion").asInt()!=1)throw fail(code,"schemaVersion must be 1");}
    static String string(JsonNode n,String field,int max){if(n==null||!n.isTextual()||n.asText().isBlank()||n.asText().length()>max)throw fail("PAYLOAD_INVALID","Invalid "+field);return n.asText();}
    static long integer(JsonNode n,String field,long min,long max){if(n==null||!n.isIntegralNumber()||n.longValue()<min||n.longValue()>max)throw fail("CONFIG_INVALID","Invalid "+field);return n.longValue();}
    static JsonNode array(JsonNode n,String field,int min,int max){if(n==null||!n.isArray()||n.size()<min||n.size()>max)throw fail("PAYLOAD_INVALID","Invalid "+field);return n;}
    static void bytes(JsonNode n,int max,String code){if(Json.bytes(n)>max)throw fail(code,"Payload exceeds byte bound");}
    static RuntimeFailure fail(String code,String message){return new RuntimeFailure(code,message);}
}
